--- ADPDU (IEEE 1722.1-2021 6.2.1)
function M.add_adp(tree, tvb, off)
    tree:add(M.f.atdecc_adp_subtype, tvb(off + 0, 1))
    tree:add(M.f.atdecc_adp_message_type, tvb(off + 1, 1))
    tree:add(M.f.atdecc_adp_valid_time, tvb(off + 2, 2))
    tree:add(M.f.atdecc_adp_control_data_length, tvb(off + 2, 2))
    tree:add(M.f.atdecc_adp_entity_id, tvb(off + 4, 8))
    tree:add(M.f.atdecc_adp_entity_model_id, tvb(off + 12, 8))
    tree:add(M.f.atdecc_adp_entity_cap_efu_mode, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_address_access_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_gateway_entity, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_legacy_avc, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_association_id_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_association_id_valid, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_vendor_unique_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_class_a_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_class_b_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_gptp_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_authentication_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_authentication_required, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_persistent_acquire_supported, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_identify_control_index_valid, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_aem_interface_index_valid, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_general_controller_ignore, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_entity_not_ready, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_acmp_acquire_with_aem, tvb(off + 20, 4))
    tree:add(M.f.atdecc_adp_entity_cap_acmp_authenticate_with_aem, tvb(off + 20, 4))
